def fill_vehicle_keys(apps, schema_editor):
    Vehicle = apps.get_model("motor", "Vehicle")
    seen = set()
    for v in Vehicle.objects.all().order_by("id"):
        chassis = (v.chassis_no or "").upper().replace(" ", "")
        key = f"{v.make}|{v.model}|{v.year}|{chassis}".upper().replace(" ", "")[:90]
        if key in seen:            # legacy duplicate: keep the row but make the key unique
            key = f"{key[:80]}#{v.pk}"
        seen.add(key)
        Vehicle.objects.filter(pk=v.pk).update(vehicle_key=key, chassis_no=chassis)


